import {POS,SKILLS,supportPriorityAllowed} from './expedition-data.mjs';
export const DEFAULT_SUPPORT_ORDER=Object.freeze(Object.keys(POS));
export const SUPPORT_PRIORITY_RULE='仅显式“按辅助阵位优先”的正面阵位辅助使用。每次先排除倒下者、同技能效果仍存在或等待生效者；援护另排除本人。按个人顺序找第一组未覆盖候选，按技能上限选取，不跨阵位凑数、不预抽随机数。后续可照顾同阵位剩余队友，再转下一组；效果结束后从前重新检查。每次仍正常付款并占预备行动，不保证持续覆盖。';
export function validateSupportOrder(plan){if(!Object.hasOwn(plan,'supportOrder'))return;const value=plan.supportOrder;if(!Array.isArray(value)||value.length!==5||new Set(value).size!==5||value.some(pos=>!Object.hasOwn(POS,pos)))throw Error('辅助阵位优先须完整包含五个不同阵位');}
export function supportOrder(plan){validateSupportOrder(plan);return [...(plan.supportOrder||DEFAULT_SUPPORT_ORDER)];}
export const supportOrderLabel=plan=>supportOrder(plan).map(pos=>POS[pos]).join(' → ');
export function moveSupportOrder(plan,index,delta){if(!Number.isInteger(index)||![-1,1].includes(delta)||index<0||index>4||index+delta<0||index+delta>4)throw Error('辅助阵位移动无效');const order=supportOrder(plan);[order[index],order[index+delta]]=[order[index+delta],order[index]];return order;}
export function supportPriorityChoice(actor,units,skill){if(!supportPriorityAllowed(skill))throw Error('此技能不能使用辅助阵位优先');const id=Object.keys(SKILLS).find(key=>SKILLS[key]===skill);if(!id)throw Error('未知辅助技能');const order=supportOrder(actor),living=units.filter(u=>u.hp>0&&!u.mechanism&&u.side===actor.side&&(!skill.cover||u.id!==actor.id)),same=u=>(u.effects||[]).filter(e=>e.skill===id),eligible=living.filter(u=>!same(u).length),positions=order.map(pos=>({pos,living:living.filter(u=>u.pos===pos).length,covered:living.filter(u=>u.pos===pos&&same(u).length).length,waiting:living.filter(u=>u.pos===pos&&same(u).some(e=>e.active===false)).length,eligible:eligible.filter(u=>u.pos===pos).length})),first=positions.find(p=>p.eligible>0),targets=first?eligible.filter(u=>u.pos===first.pos).slice(0,skill.max):[];return {targets,trace:{skill:id,order,positions,selectedPosition:first?.pos||null,selected:targets.map(u=>({id:u.id,name:u.name})),limit:skill.max,excludeSelf:Boolean(skill.cover),rule:SUPPORT_PRIORITY_RULE}};}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export function supportPriorityEvidenceView(event){const p=event?.detail?.supportPriority;if(!p)return '';return `<section class=support-priority-proof><h3>实际辅助轮转</h3><p>${p.order.map(pos=>POS[pos]).join(' → ')}</p><ul>${p.positions.map(row=>`<li>${POS[row.pos]}：${row.living}名存活候选，同名覆盖${row.covered}（其中有等待效果${row.waiting}），尚未覆盖${row.eligible}。</li>`).join('')}</ul><p>${p.selectedPosition?'本次选择'+POS[p.selectedPosition]+'的'+p.selected.map(u=>esc(u.name)).join('、')+'；技能人数上限'+p.limit+'。':'目前各阵位均无可覆盖目标，本条免费检查后备。'}</p><small>${esc(SUPPORT_PRIORITY_RULE)}</small></section>`;}
export function supportOrderEditor(plan,inheritance='',canReset=false){const order=supportOrder(plan),active=plan.prep.some(r=>r.target==='supportPriority');return `<section class=support-priority-editor><h3>辅助阵位优先 ${inheritance}</h3><details ${active?'open':''}><summary>${active?'本范围有辅助使用此顺序':'展开排序 · 仅显式选用后生效'}</summary><p>正面阵位辅助可选“按辅助阵位优先”。同名效果仍在或等待时转向尚未覆盖者，效果结束后再检查；每次仍付法力/材料并占预备行动。援护排除本人；净化、自身、全队辅助和召唤沿原目标。</p>${order.map((pos,i)=>`<div class=order-row data-support-position="${pos}"><span>${i+1} · ${POS[pos]}</span><div><button data-support-order="${i}:-1" ${i===0?'disabled':''} aria-label="上移辅助${POS[pos]}">↑</button> <button data-support-order="${i}:1" ${i===4?'disabled':''} aria-label="下移辅助${POS[pos]}">↓</button></div></div>`).join('')}${canReset?'<button data-support-order-reset>恢复默认辅助顺序</button>':''}</details></section>`;}
